E["quest:94249"] = {t="quest",n="Craftsman's Writ: Azure Silk Hood",z="general",s="A faded Craftsman’s Writ requests an Azure Silk Hood and gives terms for its delivery and payment. You need the writ to complete the exchange.",h="A faded Craftsman’s Writ requests an Azure Silk Hood and gives terms for its delivery and payment.",sec={{t="The Written Terms",b="The note is penned in faded ink and names one item: an Azure Silk Hood. It also gives the place for delivery and the payment. The writ can pass from one bearer to another, but you need it with you to complete the transaction.",sp=0}},faq={{q="What does the writ ask for?",a="The customer requests one Azure Silk Hood.",al={"azure hood writ","what item is wanted","craftsman writ"}},{q="Where do I deliver the hood?",a="The delivery location is marked on your map.",al={"delivery location","where to take it","marked place"}},{q="What do I need for the transaction?",a="You need the requested item and the writ in your possession.",al={"what to bring","need the writ?","complete exchange"}},{q="Does the writ say how payment works?",a="The note includes information about payment, but the text here does not specify the amount.",al={"how much payment","payment terms","what do i get"}},{q="Can someone else carry the writ?",a="Yes. The writ is marked as transferable.",al={"transferable writ","can i pass it on","who can hold it"}}},kw={"azure silk hood","craftsman's writ","delivery","payment","silk hood","transferable","writ"},m={id=94249},src={"In-game quest text: Craftsman's Writ: Azure Silk Hood"},fv=true}
E["quest:94250"] = {t="quest",n="Craftsman's Writ: Small Silk Pack",z="general",s="A transferable writ requests one Small Silk Pack and gives details for its delivery and payment. The writ is needed to complete the exchange.",h="A transferable writ requests one Small Silk Pack and gives details for its delivery and payment.",sec={{t="The Writ",b="A customer’s faded note asks you for one Small Silk Pack. It includes where to deliver the pack and how payment will be made. The writ can pass from hand to hand, but you need to hold it when the exchange is completed.",sp=0}},faq={{q="What does the writ ask for?",a="The customer requests one Small Silk Pack.",al={"small silk pack writ","what item is requested","silk pack request"}},{q="Where do I deliver the pack?",a="The writ provides delivery information, and the location is marked on your map.",al={"delivery location","where to take it","where is the dropoff"}},{q="How is payment handled?",a="The writ includes information about payment.",al={"how much do I get","payment details","what's the payment"}},{q="Can I transfer the writ to someone else?",a="Yes. The note says the writ is transferable.",al={"is the writ transferable","give writ away","pass it on"}},{q="Do I need the writ to complete the exchange?",a="Yes. You need the writ in your possession to complete the transaction.",al={"need writ to turn in","must I keep the note","writ required"}}},kw={"craftsman's writ","delivery","payment","silk","small silk pack","transferable","writ"},m={id=94250},src={"In-game quest text: Craftsman's Writ: Small Silk Pack"},fv=true}
